// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { 
        owner = address(this);
        c = new C(owner); 
    }

    function testFuzz_property(address _sender, uint256 _amount) public {
        // Restrict: sender must be the owner, and some amount of ether to test
        vm.assume(_sender == owner);
        vm.deal(address(c), _amount);

        // Call withdrawAll as owner
        c.withdrawAll(_sender);

        // General rule: after withdrawAll, contract balance is always zero
        assertTrue(address(c).balance == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address anySender, uint256 amount) public {
        vm.assume(anySender != address(0));
        vm.deal(address(c), amount);
        // Simulate any sequence of calls (here just one transfer in and then withdrawAll as owner)
        // But the rule must be general: after withdrawAll called by owner, balance is zero.
        // Drive the contract: call withdrawAll from the owner (this contract).
        c.withdrawAll(address(this));
        // General rule: the contract's balance is zero after withdrawAll from owner.
        assertTrue(address(c).balance == 0);
    }
}

